// `people` comes from the adapter's built-in profile.
//
// Returns a wrapper object for the known response body format(s).
//
// Corresponds with GET /api/v1/adapters (the `ListAdapters` operationId).
func (c *ClientWithResponses) ListAdaptersWithResponse(ctx context.Context, reqEditors ...RequestEditorFn) (*ListAdaptersResponse, error) {
	rsp, err := c.ListAdapters(ctx, reqEditors...)
	if err != nil {
		return nil, err
	}
	return ParseListAdaptersResponse(rsp)
}

// UpdateAdapterWithBodyWithResponse Turn a tool on or off for the whole organisation
//
